<script>
import axios from 'axios'

export default {
  name: 'PmtGet',
  methods: {
    async getPmt(jsonPath) {
      const net = '' 
      const net_files = `${net}/files`

      const difColor_map = {
        'EZ': '#0D9A28',
        'HD': '#0175B8',
        'IN': '#CF1313',
        'AT': '#383838'
      }

      try {
        const response = await axios.get(jsonPath)
        const jsonData = response.data

        for (const songId of Object.keys(jsonData)) {
          const song = jsonData[songId]
          song.cover = `${net}/assets/illLow/${songId}.png`

          for (const diff of ['EZ', 'HD', 'IN', 'AT']) {
            if (song[diff]) {
              song[diff].color = difColor_map[diff]
            }
          }
        }

        return jsonData;

      } catch (error) {
        console.error('获取数据失败：', error)
        console.error('请求路径：', jsonPath)
        return {}
      }
    }
  }
}
</script>