<template>
  <div class="song-card" :style="{ background: mainColor }" @click="goToLink">
    <div class="rank-box">
      <span class="rank-text">#{{ songData.rank }}</span>
    </div>

    <div class="song-info">
      <h2 class="song-name" :style="{ color: textColor }">{{ songData.name }}</h2>
      <p class="song-id" :style="{ color: textColor, opacity: 0.8 }">@{{ songData.id }}</p>
    </div>

    <div class="right-group">
      <div class="song-score" :style="{ color: textColor }">
        {{ Number(songData.score).toFixed(4) }}
      </div>
    </div>
  </div>

  
</template>

<script setup>
const props = defineProps({
  songData: {
    type: Object,
    required: true
  },
  mainColor: {
    type: String,
    required: true
  },
  textColor: {
    type: String,
    required: true
  }
})

const formatTime = (timeStr) => {
  if (!timeStr) return ''
  const [date, time] = timeStr.split(' ')
  const [y, m, d] = date.split('.')
  return `${y.slice(2)}/${m}/${d} ${time}`
}

const goToLink = () => {
  if (props.songData.bvid) {
    const fullUrl = `https://www.bilibili.com/video/${props.songData.bvid}`;
    window.open(fullUrl, '_blank');
  }
}
</script>

