<script setup>
import pmtGet from './components/pmtGet.vue'
import pmtCard from './components/pmtCard.vue'
import { ref, onMounted, computed } from 'vue'
import { useRouter } from 'vue-router'

const router = useRouter()
const songList = ref({})
const showType0 = ref(false)
const selectedYear = ref('2026')

const yearConfig = {
  2024: {
    color: '#3E3146',
    text: '#F7ED01',
    file: '/files/pmt/maps2024.json'
  },
  2025: {
    color: '#323232',
    text: '#FF8E34',
    file: '/files/pmt/maps2025.json'
  },
  2026: {
    color: '#002E47',
    text: '#FFFFFF',
    file: '/files/pmt/maps2026.json'
  }
}

const yearColor = computed(() => yearConfig[selectedYear.value].color)
const yearTextColor = computed(() => yearConfig[selectedYear.value].text)

const filteredSongList = computed(() => {
  const result = {}
  for (const key in songList.value) {
    const item = songList.value[key]
    if (!showType0.value && item?.Type !== 1) continue
    result[key] = item
  }
  return result
})

const fetchSongData = async () => {
  try {
    const filePath = yearConfig[selectedYear.value].file
    const data = await pmtGet.methods.getPmt(filePath)
    songList.value = data
  } catch (error) {
    console.error('获取歌曲数据失败：', error)
    songList.value = {}
  }
}

const changeYear = (year) => {
  selectedYear.value = year
  fetchSongData()
}

onMounted(async () => {
  await fetchSongData()
})

const goToTable = (tableName) => {
  router.push({ name: tableName })
}

const handleLink = (link) => {
  if (link.startsWith('/') || !link.includes('http')) {
    goToTable(link)
  } else {
    window.open(link, '_blank')
  }
}
</script>

<template>
  <div class="song-container">
    <div class="control-wrapper">
      <div class="year-tabs">
        <button
          :class="['year-btn', { active: selectedYear === '2024' }]"
          @click="changeYear('2024')"
          :style="{ backgroundColor: selectedYear === '2024' ? yearColor : '#f5f5f5', color: selectedYear === '2024' ? yearTextColor : '#000000' }"
        >
          2024
        </button>
        <button
          :class="['year-btn', { active: selectedYear === '2025' }]"
          @click="changeYear('2025')"
          :style="{ backgroundColor: selectedYear === '2025' ? yearColor : '#f5f5f5', color: selectedYear === '2025' ? yearTextColor : '#000000' }"
        >
          2025
        </button>
        <button
          :class="['year-btn', { active: selectedYear === '2026' }]"
          @click="changeYear('2026')"
          :style="{ backgroundColor: selectedYear === '2026' ? yearColor : '#f5f5f5', color: selectedYear === '2026' ? yearTextColor : '#000000' }"
        >
          2026
        </button>
      </div>

      <div class="toggle-wrapper" v-if="Number(selectedYear) < 2026">
        <span class="toggle-text">
          {{ showType0 ? '决赛图池' : '海选图池' }}
        </span>
        <label class="toggle-switch">
          <input
            v-model="showType0"
            type="checkbox"
          >
          <span class="slider"></span>
        </label>
      </div>
    </div>

    <div v-for="(songItem, songKey) in filteredSongList" :key="songKey" class="song-section">
      <pmt-card class="song-card" 
      :song-data="songItem" 
      :song-key="songKey" 
      :main-color="yearColor"
      :text-color="yearTextColor" />
    </div>
  </div>
</template>

<style scoped>
.song-container {
  max-width: 1500px;
  margin: 0 auto;
  padding: 20px;
}

.control-wrapper {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 24px;
}

.year-tabs {
  display: flex;
  gap: 8px;
}

.year-btn {
  padding: 6px 16px;
  border: none;
  font-size: 18px;
  font-weight: 500;
  cursor: pointer;
  user-select: none;
}

.song-section {
  margin-bottom: 16px;
}

.song-card {
  width: 100%;
}

.toggle-wrapper {
  display: flex;
  align-items: center;
  gap: 12px;
  font-weight: 500;
}

.toggle-switch {
  position: relative;
  display: inline-block;
  width: 56px;
  height: 28px;
}

.toggle-switch input {
  opacity: 0;
  width: 0;
  height: 0;
}

.slider {
  position: absolute;
  cursor: pointer;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: v-bind(yearColor);
}

.slider:before {
  position: absolute;
  content: "";
  height: 20px;
  width: 20px;
  left: 4px;
  bottom: 4px;
  background-color: v-bind(yearTextColor);
}

input:checked + .slider {
  background-color: v-bind(yearColor);
}

input:checked + .slider:before {
  transform: translateX(28px);
}

.toggle-text {
  user-select: none;
  color: var(--color-text);
  font-size: 18px;
}
</style>