<script>
import axios from 'axios'

export default {
  name: 'YFPSGet',
  methods: {
    async getYFPS(jsonPath) {
      const net = '' 
      const net_files = `${net}/files`

      try {
        const response = await axios.get(jsonPath)
        const jsonData = response.data

        for (const songId of Object.keys(jsonData)) {
          const song = jsonData[songId]
          song.cover = `${net}/assets/illLow/${songId}.png`
        }

        return jsonData

      } catch (error) {
        console.error('获取数据失败：', error)
        console.error('实际请求的JSON文件路径：', jsonPath)
        return {}
      }
    }
  }
}
</script>