<script setup>
import pmtPGet from './components/pmtPGet.vue'
import pmtPCard from './components/pmtPCard.vue'
import pmtRGet from './components/pmtRGet.vue'
import pmtRCard from './components/pmtRCard.vue'
import { ref, onMounted, computed } from 'vue'

const yearConfig = {
  2024: {
    color: '#3E3146',
    text: '#F7ED01',
    file: '/files/pmt/sea2024.json',
    dataFile: '/files/pmt/data2024.json'
  },
  2025: {
    color: '#323232',
    text: '#FF8E34',
    file: '/files/pmt/sea2025.json',
    dataFile: '/files/pmt/data2025.json'
  },
  2026: {
    color: '#002E47',
    text: '#FFFFFF',
    file: '/files/pmt/sea2026.json',
    dataFile: '/files/pmt/data2026.json'
  }
}

const selectedYear = ref('2026')
const songList = ref({})
const rankList = ref([])
const yearColor = computed(() => yearConfig[selectedYear.value].color)
const yearTextColor = computed(() => yearConfig[selectedYear.value].text)

const fetchSongData = async () => {
  try {
    const filePath = yearConfig[selectedYear.value].file
    const fileRankPath = yearConfig[selectedYear.value].dataFile
    const data = await pmtPGet.methods.getPlayer(filePath)
    const rank = await pmtRGet.methods.getRank(fileRankPath)
    
    songList.value = data
    rankList.value = rank || []
  } catch (error) {
    console.error('获取数据失败：', error)
    songList.value = {}
    rankList.value = []
  }
}

const changeYear = (year) => {
  selectedYear.value = year
  fetchSongData()
}

onMounted(async () => {
  await fetchSongData()
})
</script>

<template>
  <div class="song-container">
    <div class="control-wrapper">
      <div class="year-tabs">
        <button
          :class="['year-btn', { active: selectedYear === '2025' }]"
          @click="changeYear('2025')"
          :style="{ backgroundColor: selectedYear === '2025' ? yearColor : '#f5f5f5', color: selectedYear === '2025' ? yearTextColor : '#000000' }"
        >
          2025
        </button>
        <button
          :class="['year-btn', { active: selectedYear === '2026' }]"
          @click="changeYear('2026')"
          :style="{ backgroundColor: selectedYear === '2026' ? yearColor : '#f5f5f5', color: selectedYear === '2026' ? yearTextColor : '#000000' }"
        >
          2026
        </button>
      </div>
    </div>

    <div class="rank-wrapper">
      <div v-for="(list, title) in rankList" :key="title" class="rank-section">
        <h2 class="rank-title" :style="{ color: yearTextColor }">
          <template v-if="title === '季军'">
            PMT{{ selectedYear }}-3强
          </template>
          <template v-else>
            {{ ['冠军','亚军','季军'].includes(title) ? '' : `PMT${selectedYear}-${title}` }}
          </template>
        </h2>

        <pmt-r-card
          :song-data="list"
          :group-title="title"
          :main-color="yearColor"
          :text-color="yearTextColor"
        />
      </div>
    </div>

    <div class="rank-title" :style="{ color: yearTextColor }">PMT{{ selectedYear }} 预选赛晋级得分</div>
    <div class="card-grid">
      <div
        v-for="(songItem, songKey) in songList"
        :key="songKey"
        class="grid-item"
      >
        <pmt-p-card
          :song-data="songItem"
          :song-key="songKey"
          :main-color="yearColor"
          :text-color="yearTextColor"
        />
      </div>
    </div>
  </div>
</template>

<style scoped>
.empty-tip {
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-text-sub);
  padding: 30px 0;
  font-size: 14px;
}

.title-tip {
  display: flex;
  padding: 45px 0;
  align-items: center;
  justify-content: center;
  color: var(--color-text);
  font-size: 35px;
}

.song-container {
  max-width: 1500px;
  margin: 0 auto;
  padding: 20px;
}

.card-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 20px;
}

.grid-item {
  width: 100%;
}

:deep(.pmt-p-card),
:deep(.pmt-r-card) {
  width: 100%;
}

.control-wrapper {
  display: flex;
  justify-content: flex-start;
  align-items: center;
  margin-bottom: 10px;
}

.year-tabs {
  display: flex;
  gap: 8px;
}

.year-btn {
  padding: 6px 16px;
  border: none;
  font-size: 18px;
  font-weight: 500;
  cursor: pointer;
  user-select: none;
}

.rank-wrapper {
  width: 100%;
  margin-top: 20px;
}
.rank-section {
  margin-bottom: 40px;
}
.rank-title {
  font-size: 32px;
  font-weight: bold;
  margin: 0 0 20px 0;
  text-align: center;    
  width: 100%;           
}
</style>